            return False
        if side1 + side2 <= side3 or side1 + side3 <= side2 or side2 + side3 <= side1:
            return False
        return True

    if not is_valid_triangle(side1, side2, side3):
        return -1

    s = (side1 + side2 + side3) / 2
    area = calculate_area(s, side1, side2, side3)
    return area

